<div class="text-center py-5">
    <h1>Shipment Tracker</h1>
    <p class="lead">Track your shipment with a tracking number</p>

    <div class="row justify-content-center mt-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-ABC)"
                       @bind="trackingNumber" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                    Track
                </button>
            </div>
        </div>
    </div>
</div>

@code {
    private string trackingNumber = "";

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Navigation.NavigateTo($"/track/{trackingNumber.Trim()}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") TrackShipment();
    }
}

arguments.file_text:
@page "/track/{TrackingNumber}"

@inject IShipmentService ShipmentService

<PageTitle>Track Shipment - @TrackingNumber</PageTitle>

<h2>Tracking: @TrackingNumber</h2>

@if (loading)
{
    <p><em>Loading...</em></p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">No shipment found with tracking number <strong>@TrackingNumber</strong>.</div>
}
else
{
    <div class="card mt-3">
        <div class="card-body">
            <h5 class="card-title">@shipment.Description</h5>
            <div class="mb-3">
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <table class="table">
                <tbody>
                    <tr><th>Origin</th><td>@shipment.Origin</td></tr>
                    <tr><th>Destination</th><td>@shipment.Destination</td></tr>
                    <tr><th>Estimated Delivery</th><td>@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</td></tr>
                    <tr><th>Last Updated</th><td>@shipment.LastUpdated.ToString("MMM dd, yyyy HH:mm UTC")</td></tr>
                </tbody>
            </table>
        </div>
    </div>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = "";

    private ShipmentDto? shipment;
    private bool loading = true;

    protected override async Task OnParametersSetAsync()
    {
        loading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatcher"
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <h4 class="mt-4">Create New Shipment</h4>
    <div class="row g-2 mb-4">
        <div class="col-md-2">
            <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
        </div>
        <div class="col-md-2">
            <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
        </div>
        <div class="col-md-2">
            <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
        </div>
        <div class="col-md-2">
            <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
        </div>
        <div class="col-md-2">
            <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
        </div>
        <div class="col-md-2">
            <button class="btn btn-success w-100" @onclick="CreateShipment">Create</button>
        </div>
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Last Updated</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in shipments)
            {
                <tr>
                    <td>@s.TrackingNumber</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.LastUpdated.ToString("MMM dd, HH:mm")</td>
                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                @onchange="(e) => UpdateStatus(s.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == s.Status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto> shipments = [];
    private ShipmentDto newShipment = new();
    private bool loading = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber)) return;
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new();
        await LoadShipments();
    }

    private async Task UpdateStatus(Guid id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            await LoadShipments();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

